from audit_utils import *
for tree,layer in [('fr_printed','French as printed'),('fr','French corrected')]:
 rel=f'sources/{tree}/fr/149.tex'
 def r(a,b,line,statement='',kind='reading',why='',count=1):
  replace(rel,a,b,layer,'149-187',line,statement,'400-dpi scan, enlarged page bands and tight degree crop. '+why,kind,count=count)
 txt,_,_=page_text(rel,187)
 label=r'\result{COROLLAIRE}{} '; a=txt.index(label)+len(label); b=txt.index('\n\n',a);old=txt[a:b]
 r(old,underline_prose(old),'lines 1–2','6-cor',why='The corollary prose is underlined.')
 r('locale ; par suite,','locale, par suite,','line 4','6-cor',why='The print uses a comma, not a semicolon.')
 r('(cf. [4]','(cf [4]','line 12','6-cor',why='The abbreviation cf before [4] has no full stop; cf. before [3] retains its printed stop.')
 r('(Nagata)','(NAGATA)','line 15','6-cor',why='The surname is printed in capitals.')
 r('Cohen--Macaulay','Cohen-Macaulay','line 16','6-cor',why='The compound name has a single hyphen.')
 if tree=='fr_printed':
  txt,_,_=page_text(rel,187)
  for a,b,body in list(footnotes(txt)):r(txt[a:b],'','after cf. [3]','6-cor','structure','The correction note is editorial and not in the scan.')
  r('si $X$ est normale','si $S$ est normale','lines 9–10','6-cor',why='The print says S. Corrected French retains X, the variety discussed throughout this paragraph.')
  r('est une dualité entre $H^{m}(X)$','est une dualité entre $H^{n}(X)$','section 7, line 8','7-duality',why='The exponent is visibly n. The corrected m in the supplied source is justified by the displayed product, which pairs degree m with degree 2n-m.')
 r(r'\fsection{7}{La dualité de Poincaré}',r'\fsection{\normalfont7}{\normalfont\uline{La dualité de Poincaré}.}','heading','7',why='The section title is underlined and ends with a period.')
 r('Alors\n\\[\n  H^{**}(X)=H^{*}(X,\\Omega_X^{*})\n\\]\nest','Alors\n$H^{**}(X)=H^{*}(X,\\Omega_X^{*})$ est','section 7, lines 1–2','7','structure','The cohomology definition runs in the line; the crowded double-star reading is retained provisionally and flagged for the second reading.')
 r('le corps de base $k$, et le produit\n\\[\n  H^{m}(X)\\times H^{2n-m}(X)\\longrightarrow H^{2n}(X)=k\n\\]\nest','le corps de base $\\underline{k}$, et le produit\n$H^{m}(X)\\times H^{2n-m}(X)\\longrightarrow H^{2n}(X)=\\underline{k}$ est','section 7, lines 7–8','7-duality','structure','The product runs in the line; the two field letters are underlined, unlike the earlier integer k.')
 r(r'H^{*}(X\times Y)=H^{*}(X)\otimes H^{*}(Y),',r'H^{*}(X\times Y)=H^{*}(X)\otimes H^{*}(Y)','formula 7.1','7.1',why='There is no comma after the display.')
 txt,_,_=page_text(rel,187)
 for m in list(re.finditer('« (.*?) »',txt,re.S)):
  r(m.group(0),r'\fquote{'+m.group(1)+'}','quoted terminology','6;7',why='The scan has ordinary double quotation marks.')
 txt,_,_=page_text(rel,187)
 for m in list(re.finditer(r'\$[^$]+\$',txt)):
  old=m.group(0);new=old.replace(r'\Omega',r'\underline{\Omega}')
  if new!=old:r(old,new,'section 7 differential-sheaf symbols','7',why='Capital Omega is underlined in print.')
 upright_page(rel,layer,'149-187')
event('149-6-cor','targeted proof check','By Proposition 6, the vanishing is equivalent to H^0(E^{n-i}(F)(m))=0 for all sufficiently large m. Lemma 3 makes these twists generated by global sections, so that condition is equivalent to the coherent sheaf E^{n-i}(F) being zero. This supplies the implication used in Theorem 3 bis. The isolated printed S in the normality example must be X, the only variety in that paragraph.','149, p. 187, Corollary and following paragraph')
event('149-7-duality-print','refuted, with the refined statement\'s id','The printed sentence pairs H^n(X) with H^{2n-m}(X), although its immediately preceding product has first degree m. The degree must be m, since only complementary total degrees sum to 2n. The corrected statement is 149-7-duality.','149, p. 187, section 7, first paragraph, duality sentence')
event('149-7-duality','targeted proof check','For smooth projective X, the wedge pairing Omega^q tensor Omega^{n-q} to Omega^n identifies the two vector bundles as Serre duals. Theorem 3 therefore gives perfect pairings H^p(Omega^q) with H^{n-p}(Omega^{n-q}), of complementary total degrees m and 2n-m. This confirms the corrected m and the Poincare pairing described here.','149, p. 187, section 7, first paragraph')
event('149-7.1','carried as background without fault found','Read the Kunneth formula and stated compatibility with Poincare algebras. The algebra is graded-commutative by the preceding anticommutativity convention; the printed later word commutative is not silently expanded.','149, p. 187, (7.1) and following paragraph')
record_page('149',187,r'''Compared sources/fr_printed/fr/149.tex entry lines 954–1003 and sources/fr/fr/149.tex entry lines 961–1010 against scan leaf 20, rendered at 400 dpi, the enlarged top/middle/bottom bands and a tight crop of the exponent in the duality sentence. Read the Corollary, all local examples and the opening of section 7 through the sentence continued on p. 188.

Both layers restore exact punctuation, capital NAGATA, the single hyphen, ordinary quotes, underlining, the inline definition and inline product, field and sheaf underlines, and upright variables. Printed French restores S in the normality example and n in the sentence describing the duality; corrected French retains the supplied X and m. The first is required by the paragraph's referent; the second by the complementary degrees in the immediately preceding product. The printed first cohomology superscript is crowded/overstruck; the supplied double-star transcription has been retained provisionally, with this uncertainty reserved for the mandated second reading. The corollary's equivalence was checked using eventual global generation, completing the deferred implication in Theorem 3 bis.''')
